param([string] $ArtifactsRoot = 'C:\Users\17917\AppData\Local\Temp\Card-slowchecks-20261009-07ac82c4')
$ErrorActionPreference = 'Stop'
$normalOutput = Join-Path $ArtifactsRoot 'bin\CardGame.Core.Tests\release'
$coreAssembly = [Reflection.Assembly]::LoadFrom((Join-Path $normalOutput 'CardGame.Core.dll'))
$null = [Reflection.Assembly]::LoadFrom((Join-Path $normalOutput 'CardGame.Content.Standard.dll'))
$testAssembly = [Reflection.Assembly]::LoadFrom((Join-Path $normalOutput 'CardGame.Core.Tests.dll'))
$staticPrivate = [Reflection.BindingFlags]'Static,NonPublic'
$instancePrivate = [Reflection.BindingFlags]'Instance,NonPublic'
$gameType = $coreAssembly.GetType('CardGame.Core.GameEngine')
$rows = [Collections.Generic.List[object]]::new()

# Host grant/chain state is a legal mechanism combination, not replay input.
# The target-adjustment grants below come from real accepted fixture commands.
foreach ($mechanism in @('next-actual-use', 'red-additional-targets')) {
    if ($mechanism -eq 'next-actual-use') {
        $fixtureType = $testAssembly.GetType('BoundaryJianYongChecks')
        $pair = $fixtureType.GetMethod('Create',$staticPrivate).Invoke($null,[object[]]@($true,$false,$false,$false))
        $game = $pair.Item1
        $registry = $pair.Item2
        $null = $fixtureType.GetMethod('ReachPlay',$staticPrivate).Invoke($null,[object[]]@($game))
        $paid = $fixtureType.GetMethod('Contest',$staticPrivate).Invoke($null,[object[]]@($game,$registry,1,$true))
        $issued = $gameType.GetMethod('CurrentNextActualUseAdjustment',$instancePrivate).Invoke($game,[object[]]@(0))
        $grantEvidence = [pscustomobject]@{ PaidSourceWon=$paid.SourceWon; ProgramFrameId=$issued.ProgramFrameId }
    } else {
        $fixtureType = $testAssembly.GetType('Fame2017WuXianChecks')
        $pair = $fixtureType.GetMethod('Create',$staticPrivate).Invoke($null,[object[]]@($false,$false,$false))
        $game = $pair.Item1
        $registry = $pair.Item2
        $null = $fixtureType.GetMethod('Choose',$staticPrivate).Invoke($null,[object[]]@($game,'targets'))
        $predicate = [Func[CardGame.Core.PendingDecision,bool]] { param($decision) $decision.Kind.ToString() -eq 'PlayCard' }
        $null = $fixtureType.GetMethod('Reach',$staticPrivate).Invoke($null,[object[]]@($game,$predicate))
        $issued = $gameType.GetField('_redAdditionalTargetGrants',$instancePrivate).GetValue($game).get_Item(0)
        $grantEvidence = [pscustomobject]@{ Source=$issued.Item1; Maximum=$issued.Item2 }
    }
    $owner = $gameType.GetField('_players',$instancePrivate).GetValue($game)[0]
    $grant = $coreAssembly.GetType('CardGame.Core.SkillGrant').GetConstructors()[0].Invoke([object[]]@(
        'zero-repro-grant','ol:xianwan','zero-repro-instance','acquired:zero-repro',$true,$null,$null,$null,$null,$null))
    $null = $owner.SkillGrants.Grant($grant)
    $owner.IsChained = $true
    $legalZero = $gameType.GetMethod('ChainedStateBasicPlayActions',$instancePrivate).Invoke($game,[object[]]@($owner))
    foreach ($selected in @($null,0)) {
        $failure = $null
        try { $null = $gameType.GetMethod('BuildLegalActions',$instancePrivate).Invoke($game,[object[]]@($owner,$true,$selected)) }
        catch { $failure=$_.Exception; while ($failure.InnerException) { $failure=$failure.InnerException } }
        $rows.Add([pscustomobject]@{
            Mechanism=$mechanism; SelectedPhysicalCardId=$selected; Grant=$grantEvidence
            LegalZeroCount=$legalZero.Count; LegalZeroFirst=($legalZero | Select-Object -First 1)
            ErrorType=$(if ($failure) { $failure.GetType().FullName } else { $null })
            ErrorMessage=$failure.Message; Stack=$failure.StackTrace
        })
    }
}
[pscustomobject]@{
    CoreSha256=(Get-FileHash -Algorithm SHA256 -LiteralPath (Join-Path $normalOutput 'CardGame.Core.dll')).Hash
    Note='Real accepted paid/benefit prefix followed by explicit legal host skill+chain combination; no fabricated actions or adjustment grants, no claim of replaying host mutations.'
    Cases=$rows
} | ConvertTo-Json -Depth 9
